(() => {
  'use strict';
  const dialog=document.querySelector('#curiosity-dialog'),trigger=document.querySelector('.curiosity-trigger');
  trigger.setAttribute('aria-label','Play with the 3D guide');trigger.querySelector('.curiosity-hint').textContent='3D GUIDE ↗';
  const pages=[['home','Home','The introduction. Start with a little possibility.','⌂'],['about','About','Meet the person, interests, and tools behind the work.','⌘'],['projects','Projects','Explore three ideas brought to life.','</>'],['photography','Photography','A place for moments outside the screen.','⌑'],['beyond','Beyond the Screen','Badminton, volleyball, football, and life away from the keyboard.','◇'],['playground','Playground','Experiment with data and try a reaction challenge.','✦'],['board-games','Board Games','A collection of games, ready for the next move.','♟'],['books','Books','Stories, ideas, and a short introduction to each book.','▤'],['contact','Contact','Start a conversation and see where an idea can go.','↗']];
  const cube=(name,front)=>`<div class="bot-part ${name}">${['front','back','left','right','top','bottom'].map(side=>`<div class="bot-face ${side}">${side==='front'?front:''}</div>`).join('')}</div>`;
  dialog.classList.add('robot-dialog');
  dialog.innerHTML=`<div class="robot-dialog-bar"><p class="eyebrow">ZW / YOUR LITTLE GUIDE</p><button class="close-dialog" aria-label="Close curiosity explorer">×</button></div><div class="robot-dialog-content"><h2 id="curiosity-title">Meet Byte.<br><em>Your curious companion.</em></h2><p class="curiosity-intro">Turn Byte around, give it some energy, or ask for a little dance. Then choose where to explore.</p><div class="robot-stage" tabindex="0" role="group" aria-label="Rotate the 3D robot" aria-describedby="robot-help"><div class="robot-floor" aria-hidden="true"></div><div class="robot-object" aria-hidden="true"><div class="bot-antenna"></div>${cube('bot-head','<div class="bot-visor"></div><div class="bot-eyes"><i></i><i></i></div><span class="bot-mouth"></span>')}${cube('bot-body','<span class="bot-badge">&lt;/&gt;</span>')}${cube('bot-arm arm-left','')}${cube('bot-arm arm-right','')}<div class="bot-foot foot-left"></div><div class="bot-foot foot-right"></div></div><span class="robot-coordinate" aria-hidden="true">X −12° / Y −22°</span></div><div class="robot-tools"><span id="robot-help">Drag / use arrow keys when focused</span><button class="text-link" id="robot-wave">Say hello ✦</button><button class="text-link" id="robot-dance">Dance ♫</button><button class="text-link" id="robot-spin">Spin ↻</button><button class="text-link" id="robot-reset">Reset view</button></div><div class="robot-energy"><button id="robot-charge" type="button">Charge Byte ⚡</button><div class="energy-track" role="progressbar" aria-label="Byte energy" aria-valuemin="0" aria-valuemax="3" aria-valuenow="0"><span></span></div><p id="robot-reaction" role="status">Three taps to power up. No rush.</p></div><div class="robot-routes" role="group" aria-label="Choose a page">${pages.map(([id,name,,icon])=>`<button data-robot-page="${id}" aria-pressed="false"><span aria-hidden="true">${icon}</span>${name}</button>`).join('')}</div><div class="robot-selection" aria-live="polite"><h3></h3><p></p></div><a class="button primary curiosity-destination" href="#projects">Explore Projects ↗</a></div>`;
  const stage=dialog.querySelector('.robot-stage'),figure=dialog.querySelector('.robot-object');let x=-12,y=-22,drag=null,wave=null,frame=0,shownX=x,shownY=y,last=0,energy=0;
  const coordinate=dialog.querySelector('.robot-coordinate'),moves=new Set();
  function animate(part,keys,options){if(window.portfolioMotion.matches)return;const a=part.animate(keys,options);moves.add(a);a.finished.then(()=>moves.delete(a),()=>moves.delete(a));return a;}
  function stop(){moves.forEach(a=>a.cancel());moves.clear();cancelAnimationFrame(frame);frame=0;last=0;x=shownX;y=shownY;}
  function render(time){frame=0;const blend=1-Math.exp(-Math.min(last?time-last:16,40)/55);last=time;shownX+=(x-shownX)*blend;shownY+=(y-shownY)*blend;figure.style.transform=`rotateX(${shownX}deg) rotateY(${shownY}deg)`;if(Math.abs(x-shownX)+Math.abs(y-shownY)>.05)frame=requestAnimationFrame(render);else last=0;}
  function react(text){dialog.querySelector('#robot-reaction').textContent=text;}
  function dance(){stop();react('Byte found its rhythm. Your turn!');animate(figure,[{translate:'0 0',rotate:'0deg'},{translate:'-12px -8px',rotate:'-8deg'},{translate:'12px -15px',rotate:'8deg'},{translate:'-10px -6px',rotate:'-6deg'},{translate:'0 0',rotate:'0deg'}],{duration:1200,easing:'ease-in-out',iterations:2});animate(dialog.querySelector('.bot-head'),[{rotate:'0deg'},{rotate:'8deg'},{rotate:'-8deg'},{rotate:'0deg'}],{duration:600,iterations:4});}
  dialog.querySelector('#robot-dance').addEventListener('click',dance);
  dialog.querySelector('#robot-spin').addEventListener('click',()=>{stop();y+=360;paint();react('A fresh perspective. Try dragging to find your favourite angle.');});
  dialog.querySelector('#robot-charge').addEventListener('click',()=>{energy=energy===3?1:energy+1;const meter=dialog.querySelector('.energy-track');meter.setAttribute('aria-valuenow',energy);meter.firstElementChild.style.transform=`scaleX(${energy/3})`;dialog.classList.toggle('is-charged',energy===3);if(energy===3){dance();react('Fully charged! Byte celebrates with a dance. Tap again to recharge.');}else{react(energy===1?'One spark collected. Two more to go!':'Almost there. One more spark!');animate(dialog.querySelector('.bot-head'),[{translate:'0 0'},{translate:'0 -6px'},{translate:'0 0'}],{duration:250});}});
  function paint(){coordinate.textContent=`X ${Math.round(x)}° / Y ${Math.round(y)}°`;if(window.portfolioMotion.matches){shownX=x;shownY=y;figure.style.transform=`rotateX(${x}deg) rotateY(${y}deg)`;}else if(!frame)frame=requestAnimationFrame(render);}
  function select(id){const page=pages.find(p=>p[0]===id)||pages[2];dialog.querySelectorAll('[data-robot-page]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.robotPage===page[0])));dialog.querySelector('.robot-selection h3').textContent=page[1];dialog.querySelector('.robot-selection p').textContent=page[2];dialog.querySelector('.curiosity-destination').href='#'+page[0];dialog.querySelector('.curiosity-destination').textContent='Explore '+page[1]+' ↗';dialog.querySelector('.bot-badge').textContent=page[3];dialog.dispatchEvent(new CustomEvent('byte:page',{detail:page[0]}));}
  stage.addEventListener('pointerdown',event=>{if(event.button!==0)return;stop();drag={id:event.pointerId,x:event.clientX,y:event.clientY,rx:x,ry:y};stage.setPointerCapture(event.pointerId);stage.classList.add('dragging');stage.focus({preventScroll:true});});
  stage.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.id)return;x=Math.max(-45,Math.min(45,drag.rx-(event.clientY-drag.y)*.35));y=drag.ry+(event.clientX-drag.x)*.65;paint();});
  function release(){drag=null;stage.classList.remove('dragging');}
  stage.addEventListener('pointerup',release);stage.addEventListener('pointercancel',release);stage.addEventListener('lostpointercapture',release);
  stage.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(event.key))return;event.preventDefault();if(event.key==='Home'){x=-12;y=-22;}else if(event.key==='ArrowLeft')y-=15;else if(event.key==='ArrowRight')y+=15;else x=Math.max(-45,Math.min(45,x+(event.key==='ArrowUp'?-10:10)));paint();});
  dialog.addEventListener('click',event=>{const choice=event.target.closest('[data-robot-page]');if(choice)select(choice.dataset.robotPage);});
  dialog.querySelector('#robot-reset').addEventListener('click',()=>{stop();x=-12;y=-22;energy=0;dialog.classList.remove('is-charged');dialog.querySelector('.energy-track').setAttribute('aria-valuenow','0');dialog.querySelector('.energy-track span').style.transform='scaleX(0)';react('Three taps to power up. No rush.');paint();});
  dialog.querySelector('#robot-wave').addEventListener('click',()=>{
    wave?.cancel();dialog.querySelector('.robot-selection h3').textContent='Hello, curious human.';
    dialog.querySelector('.robot-selection p').textContent='Pick a page below the figure. I’ll show you where to go.';
    if(!window.portfolioMotion.matches)wave=animate(dialog.querySelector('.arm-right'),[{rotate:'0deg'},{rotate:'-115deg'},{rotate:'-80deg'},{rotate:'-115deg'},{rotate:'0deg'}],{duration:900,easing:'ease-in-out'});
  });
  dialog.addEventListener('close',()=>{release();wave?.cancel();stop();});
  window.portfolioMotion.addEventListener('change',()=>{if(window.portfolioMotion.matches){wave?.cancel();stop();paint();}});
  const slot=document.createElement('section');slot.className='robot-slot';slot.innerHTML='<div><p class="eyebrow">A SMALL DETOUR / 3D</p><h2>Meet your <em>curious guide.</em></h2><p>A little figure with five places to take you. Turn it around, say hello, and choose a path.</p><button class="button primary" aria-haspopup="dialog">Play with the 3D guide ↗</button></div><div class="robot-slot-mark" aria-hidden="true">[ ◉ ◉ ]<span>&lt; / &gt;</span></div>';
  document.querySelector('#projects .chapter-end').before(slot);slot.querySelector('button').addEventListener('click',()=>{select('projects');dialog.showModal();dialog.scrollTop=0;});
  trigger.addEventListener('click',()=>{select(document.querySelector('.page.active').id);dialog.scrollTop=0;});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){release();wave?.cancel();stop();}});
  select('projects');paint();
})();
